import{_ as t,o,c as r,ag as a}from"./chunks/framework.cyF4XceO.js";const p=JSON.parse('{"title":"takoform_worker_deployment","description":"Worker Deployment (edge.forms.takoform.com/v1beta1, role deployment).","frontmatter":{"page_title":"takoform_worker_deployment Resource - takoform","subcategory":"Edge Platform Family","description":"Worker Deployment (edge.forms.takoform.com/v1beta1, role deployment)."},"headers":[],"relativePath":"docs/resources/worker_deployment.md","filePath":"docs/resources/worker_deployment.md"}'),i={name:"docs/resources/worker_deployment.md"};function s(n,e,d,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a(`<h1 id="takoform-worker-deployment" tabindex="-1">takoform_worker_deployment <a class="header-anchor" href="#takoform-worker-deployment" aria-label="Permalink to &quot;takoform_worker_deployment&quot;">​</a></h1><p>Selects which Worker Versions of one Module Worker serve traffic and in what proportion. Weights are basis points and must sum to exactly 10000 across entries; the sum is host-validated semantics because a schema cannot add weights. Rollback is re-weighting, never mutating a revision.</p><p>This is a <code>deployment</code> resource: the only mutable path for traffic movement and rollback. It selects which revisions are active.</p><p>This Experimental Form speaks the Host API v1beta1 lane and requires provider v2.1.1 or later. Provider v2.1.1 is Registry-published; release/version.json retains candidate-only descriptor metadata after owner publication. The configured host selects and operates the concrete backend; no attribute names a vendor, target, credential, price, or implementation. See the <a href="../../examples/resources/takoform_worker_deployment/resource.tf">complete example</a>.</p><h2 id="arguments" tabindex="-1">Arguments <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;Arguments&quot;">​</a></h2><ul><li><code>name</code> (String, required, forces replacement) — Portable resource name (<code>metadata.name</code>).</li><li><code>worker</code> (String, required, forces replacement) — Module Worker identity whose traffic this deployment governs. Set the name of the target <code>ModuleWorker</code> resource.</li><li><code>versions</code> (List of Object, required) — Active Worker Versions and their traffic weights in basis points. Weights must sum to exactly 10000. Each entry declares <code>worker_version</code>, <code>weight</code> (between 1 and 10000). The list must declare between 1 and 8 entries.</li><li><code>space</code> (String, optional, forces replacement) — Exact opaque SpaceID; overrides the provider default.</li><li><code>create_timeout</code> / <code>update_timeout</code> / <code>delete_timeout</code> (String, optional) — Go durations bounding each operation (defaults <code>20m</code> / <code>20m</code> / <code>30m</code>).</li></ul><h2 id="read-only-attributes" tabindex="-1">Read-only attributes <a class="header-anchor" href="#read-only-attributes" aria-label="Permalink to &quot;Read-only attributes&quot;">​</a></h2><ul><li><code>uid</code> — host-issued immutable resource identity; delete and re-create yields a new UID.</li><li><code>generation</code> — desired-state generation; increments only when the portable desired spec changes. Updates fence on it. It is also the DELETE fence, because a delete withdraws desired state like any other desired-state mutation.</li><li><code>revision</code> — representation revision; increments whenever the representation changes — a spec-changing update, new status, new outputs, or a change to another resource this one is rendered from. It is the strong ETag, and it is deliberately NOT the delete fence: a teardown removes dependents first and would otherwise be refused by a revision it moved itself.</li><li><code>conditions</code> — the complete status condition list the host reports, in its order. Each entry carries <code>type</code> (the closed <code>Ready</code> / <code>Reconciling</code> / <code>Degraded</code> / <code>Drifted</code> / <code>Blocked</code> / <code>Deleting</code> vocabulary), <code>status</code> (<code>True</code> / <code>False</code> / <code>Unknown</code>), the closed portable <code>reason</code>, an optional <code>message</code>, an optional non-portable <code>host_reason</code> naming exactly what is wrong, the <code>observed_generation</code> the status reflects, and <code>last_transition_time</code>. Conditions are host-rendered state: they change when this resource changes AND when a resource it depends on changes, with no desired spec changing anywhere, so they are read-only and a configuration must not assert them.</li><li><code>ready</code> — derived convenience: true when <code>conditions</code> carries the closed <code>Ready</code> condition with status <code>True</code>. Read <code>conditions</code> for the reason it is not.</li><li><code>outputs_json</code> — the WHOLE <code>status.outputs</code> document, JSON-serialized. This Form declares no <code>outputSchema</code>, so a conforming host omits <code>status.outputs</code> entirely and this attribute is <code>&quot;{}&quot;</code>. It stays declared because a host may publish a value no contract describes, and an undescribed value must still be reachable rather than silently dropped.</li><li><code>form_api_version</code>, <code>form_kind</code>, <code>form_definition_version</code>, <code>form_schema_digest</code> — the exact immutable FormRef this state is bound to; reads dispatch on it.</li><li><code>form_package_digest</code> — audit-only package provenance; never part of resource identity, queries, or fences.</li><li><code>relation_drift_reason</code> — internal recovery only: <code>ExternalChange</code> or <code>DependencyMissing</code> while the host reports that a resource this one references was replaced or removed out of band, null otherwise. A refresh reports the break as a warning and keeps the resource in state; the next plan then proposes an in-place re-apply of the same desired state, which is all a host needs to re-resolve and re-pin every reference. It is provider-side recovery bookkeeping — no portable wire member carries it — and configurations must not depend on it.</li><li><code>pending_operation_id</code> — internal recovery only: the host operation id of a mutation the host accepted but that did not reach a terminal state before the operation deadline, null in steady state. A refresh consults it before it reads the resource, and it is cleared only once that operation settles. It is not resource identity and configurations must not depend on it.</li></ul><h2 id="state-continuity" tabindex="-1">State continuity <a class="header-anchor" href="#state-continuity" aria-label="Permalink to &quot;State continuity&quot;">​</a></h2><ul><li><strong>Reads dispatch on the recorded FormRef.</strong> <code>WorkerDeployment</code> state is addressed under the exact <code>form_*</code> identity it records, not under this build&#39;s default create ref, so a resource created before the Form line advanced stays addressable as itself. An identity this provider build carries no codec for is a hard error naming that identity and the ones the build does carry; the provider never substitutes another exact FormRef, because a substituted query&#39;s &quot;not found&quot; is indistinguishable from deletion.</li><li><strong>A changed <code>uid</code> is an error, and state is kept.</strong> When the host serves a different <code>uid</code> under the recorded name, the resource this state was applied against is gone and something re-used its name. The provider reports a hard error naming both uids and keeps the resource in state. It does not re-bind — that would adopt a resource you never applied — and it does not remove state, which would make the next apply fail against the resource that does exist, with no plan left to repair it. Resolve it by importing the new incarnation explicitly, restoring the prior one, or deleting the host-side replacement.</li><li><strong>An unfinished mutation is resumed, not re-created.</strong> When <code>pending_operation_id</code> is set, a refresh asks the host about that operation before it reads the resource. While the operation is still running the resource may legitimately not exist yet, so its absence is not treated as deletion and the marker survives; a terminal success is verified against the exact identity and settles state; a terminal failure or an expired operation record defers to an exact read of the resource, which decides. Refresh again once the host settles.</li></ul><h2 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h2><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_worker_deployment.example NAME</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_worker_deployment.example SPACE/NAME</span></span></code></pre></div><p>Both short forms bind state to this provider build&#39;s default create FormRef. To adopt a resource created under an EARLIER definition version of this Form, name the exact identity instead. The import ID is then one JSON object — not a delimiter-joined string, because a SpaceID is opaque UTF-8 whose only forbidden character is <code>/</code>, so no separator can escape it safely:</p><div class="language-console vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">console</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">terraform import takoform_worker_deployment.example \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &#39;{&quot;space&quot;:&quot;prod&quot;,&quot;apiVersion&quot;:&quot;edge.forms.takoform.com/v1beta1&quot;,&quot;kind&quot;:&quot;WorkerDeployment&quot;,&quot;definitionVersion&quot;:&quot;0.1.0&quot;,&quot;schemaDigest&quot;:&quot;sha256:…&quot;,&quot;name&quot;:&quot;…&quot;}&#39;</span></span></code></pre></div><p><code>space</code> is optional and falls back to the provider default; the four FormRef members are all-or-nothing. An identity this provider build carries no codec for is refused, naming the identities it does carry — it is never silently rebound to the default.</p>`,15)])])}const m=t(i,[["render",s]]);export{p as __pageData,m as default};
